import { AddTaskToProjectUseCase } from '../application/use-cases/AddTaskToProjectUseCase';
import { AssignTaskUseCase } from '../application/use-cases/AssignTaskUseCase';
import { CreateProjectUseCase } from '../application/use-cases/CreateProjectUseCase';
import { CreateUserUseCase } from '../application/use-cases/CreateUserUseCase';
import { ListProjectsUseCase } from '../application/use-cases/ListProjectsUseCase';
import { ListProjectTasksUseCase } from '../application/use-cases/ListProjectTasksUseCase';
import { ListUsersUseCase } from '../application/use-cases/ListUsersUseCase';
import { MarkTaskDoneUseCase } from '../application/use-cases/MarkTaskDoneUseCase';
import { TaskAssignmentService } from '../domain/services/TaskAssignmentService';
import { ProjectController } from './http/controllers/ProjectController';
import { TaskController } from './http/controllers/TaskController';
import { UserController } from './http/controllers/UserController';
import { Controllers } from './http/routes';
import { UuidIdGenerator } from './ids/UuidIdGenerator';
import { InMemoryProjectRepository } from './persistence/InMemoryProjectRepository';
import { InMemoryTaskRepository } from './persistence/InMemoryTaskRepository';
import { InMemoryUserRepository } from './persistence/InMemoryUserRepository';

/** Composition root: wires concrete infrastructure into the use cases. */
export function buildControllers(): Controllers {
  const ids = new UuidIdGenerator();
  const users = new InMemoryUserRepository();
  const projects = new InMemoryProjectRepository();
  const tasks = new InMemoryTaskRepository();
  const assignment = new TaskAssignmentService(users);

  return {
    users: new UserController(new CreateUserUseCase(users, ids), new ListUsersUseCase(users)),
    projects: new ProjectController(
      new CreateProjectUseCase(projects, ids),
      new ListProjectsUseCase(projects),
    ),
    tasks: new TaskController(
      new AddTaskToProjectUseCase(projects, tasks, ids),
      new ListProjectTasksUseCase(projects, tasks),
      new AssignTaskUseCase(tasks, assignment),
      new MarkTaskDoneUseCase(tasks),
    ),
  };
}

